SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Table: academic_terms
CREATE TABLE IF NOT EXISTS `academic_terms` (
  `term_id` varchar(20) NOT NULL,
  `academic_year` varchar(9) NOT NULL,
  `semester` varchar(20) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PLANNED',
  PRIMARY KEY (`term_id`),
  CONSTRAINT `academic_terms_chk_1` CHECK ((`end_date` > `start_date`)),
  CONSTRAINT `academic_terms_chk_2` CHECK ((`semester` in (_cp850'ODD',_cp850'EVEN',_cp850'SUMMER'))),
  CONSTRAINT `academic_terms_chk_3` CHECK ((`status` in (_cp850'PLANNED',_cp850'ACTIVE',_cp850'COMPLETED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Data for table: academic_terms
INSERT INTO `academic_terms` (`term_id`, `academic_year`, `semester`, `start_date`, `end_date`, `status`) VALUES
('TERM-2026-ODD', '2026-2027', 'ODD', '2026-08-01', '2026-12-15', 'ACTIVE'),
('TERM-2027-EVEN', '2026-2027', 'EVEN', '2027-01-10', '2027-05-20', 'PLANNED');

-- Table: allocation_events
CREATE TABLE IF NOT EXISTS `allocation_events` (
  `event_id` bigint NOT NULL AUTO_INCREMENT,
  `section_id` varchar(30) DEFAULT NULL,
  `assignment_id` varchar(30) DEFAULT NULL,
  `event_type` varchar(50) NOT NULL,
  `previous_state` varchar(30) DEFAULT NULL,
  `new_state` varchar(30) DEFAULT NULL,
  `event_description` text,
  `event_timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`event_id`),
  KEY `section_id` (`section_id`),
  KEY `assignment_id` (`assignment_id`),
  CONSTRAINT `allocation_events_ibfk_1` FOREIGN KEY (`section_id`) REFERENCES `sections` (`section_id`),
  CONSTRAINT `allocation_events_ibfk_2` FOREIGN KEY (`assignment_id`) REFERENCES `workload_assignments` (`assignment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

