-- Table: availability
CREATE TABLE IF NOT EXISTS `availability` (
  `availability_id` bigint NOT NULL AUTO_INCREMENT,
  `faculty_id` varchar(20) NOT NULL,
  `start_datetime` datetime NOT NULL,
  `end_datetime` datetime NOT NULL,
  `availability_type` varchar(20) NOT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`availability_id`),
  KEY `faculty_id` (`faculty_id`),
  CONSTRAINT `availability_ibfk_1` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`faculty_id`),
  CONSTRAINT `availability_chk_1` CHECK ((`end_datetime` > `start_datetime`)),
  CONSTRAINT `availability_chk_2` CHECK ((`availability_type` in (_cp850'AVAILABLE',_cp850'UNAVAILABLE',_cp850'LEAVE')))
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

