-- Table: demand_forecasts
CREATE TABLE IF NOT EXISTS `demand_forecasts` (
  `forecast_id` bigint NOT NULL AUTO_INCREMENT,
  `course_id` varchar(20) NOT NULL,
  `term_id` varchar(20) NOT NULL,
  `forecast_run_id` varchar(50) NOT NULL,
  `historical_window_start` date NOT NULL,
  `historical_window_end` date NOT NULL,
  `predicted_enrollment` int NOT NULL,
  `actual_enrollment` int DEFAULT NULL,
  `forecast_method` varchar(50) NOT NULL,
  `confidence_score` decimal(5,4) DEFAULT NULL,
  `generated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`forecast_id`),
  KEY `course_id` (`course_id`),
  KEY `term_id` (`term_id`),
  CONSTRAINT `demand_forecasts_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `demand_forecasts_ibfk_2` FOREIGN KEY (`term_id`) REFERENCES `academic_terms` (`term_id`),
  CONSTRAINT `demand_forecasts_chk_1` CHECK ((`predicted_enrollment` >= 0)),
  CONSTRAINT `demand_forecasts_chk_2` CHECK (((`actual_enrollment` is null) or (`actual_enrollment` >= 0))),
  CONSTRAINT `demand_forecasts_chk_3` CHECK ((`historical_window_end` >= `historical_window_start`)),
  CONSTRAINT `demand_forecasts_chk_4` CHECK (((`confidence_score` is null) or (`confidence_score` between 0 and 1)))
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

