-- Table: faculty
CREATE TABLE IF NOT EXISTS `faculty` (
  `faculty_id` varchar(20) NOT NULL,
  `faculty_name` varchar(150) NOT NULL,
  `department_name` varchar(100) NOT NULL,
  `email` varchar(150) DEFAULT NULL,
  `max_workload_hours` decimal(5,2) NOT NULL,
  `employment_type` varchar(30) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  PRIMARY KEY (`faculty_id`),
  UNIQUE KEY `email` (`email`),
  CONSTRAINT `faculty_chk_1` CHECK ((`max_workload_hours` > 0)),
  CONSTRAINT `faculty_chk_2` CHECK ((`employment_type` in (_cp850'FULL_TIME',_cp850'PART_TIME'))),
  CONSTRAINT `faculty_chk_3` CHECK ((`status` in (_cp850'ACTIVE',_cp850'INACTIVE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

