-- Table: faculty_skills
CREATE TABLE IF NOT EXISTS `faculty_skills` (
  `skill_id` bigint NOT NULL AUTO_INCREMENT,
  `faculty_id` varchar(20) NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `proficiency_level` varchar(20) NOT NULL,
  `years_experience` decimal(4,1) DEFAULT '0.0',
  PRIMARY KEY (`skill_id`),
  UNIQUE KEY `faculty_id` (`faculty_id`,`course_id`),
  KEY `course_id` (`course_id`),
  CONSTRAINT `faculty_skills_ibfk_1` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`faculty_id`),
  CONSTRAINT `faculty_skills_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `faculty_skills_chk_1` CHECK ((`proficiency_level` in (_cp850'BEGINNER',_cp850'INTERMEDIATE',_cp850'ADVANCED',_cp850'EXPERT'))),
  CONSTRAINT `faculty_skills_chk_2` CHECK ((`years_experience` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

