-- Table: prerequisites
CREATE TABLE IF NOT EXISTS `prerequisites` (
  `prerequisite_id` bigint NOT NULL AUTO_INCREMENT,
  `course_id` varchar(20) NOT NULL,
  `prerequisite_course_id` varchar(20) NOT NULL,
  `minimum_grade` varchar(5) DEFAULT 'D',
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  PRIMARY KEY (`prerequisite_id`),
  UNIQUE KEY `course_id` (`course_id`,`prerequisite_course_id`),
  KEY `prerequisite_course_id` (`prerequisite_course_id`),
  CONSTRAINT `prerequisites_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `prerequisites_ibfk_2` FOREIGN KEY (`prerequisite_course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `prerequisites_chk_1` CHECK ((`course_id` <> `prerequisite_course_id`)),
  CONSTRAINT `prerequisites_chk_2` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

