-- Table: program_courses
CREATE TABLE IF NOT EXISTS `program_courses` (
  `program_course_id` bigint NOT NULL AUTO_INCREMENT,
  `program_id` varchar(20) NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `recommended_semester` tinyint DEFAULT NULL,
  `is_mandatory` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`program_course_id`),
  UNIQUE KEY `program_id` (`program_id`,`course_id`),
  KEY `course_id` (`course_id`),
  CONSTRAINT `program_courses_ibfk_1` FOREIGN KEY (`program_id`) REFERENCES `programs` (`program_id`),
  CONSTRAINT `program_courses_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `program_courses_chk_1` CHECK ((`recommended_semester` between 1 and 12))
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

