-- Table: registration_interests
CREATE TABLE IF NOT EXISTS `registration_interests` (
  `interest_id` bigint NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `priority` tinyint NOT NULL,
  `interest_date` date NOT NULL,
  `interest_status` varchar(20) DEFAULT 'PENDING',
  PRIMARY KEY (`interest_id`),
  UNIQUE KEY `plan_id` (`plan_id`,`course_id`),
  KEY `course_id` (`course_id`),
  CONSTRAINT `registration_interests_ibfk_1` FOREIGN KEY (`plan_id`) REFERENCES `student_plans` (`plan_id`),
  CONSTRAINT `registration_interests_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `registration_interests_chk_1` CHECK ((`priority` between 1 and 5)),
  CONSTRAINT `registration_interests_chk_2` CHECK ((`interest_status` in (_cp850'PENDING',_cp850'CONFIRMED',_cp850'WITHDRAWN')))
) ENGINE=InnoDB AUTO_INCREMENT=6001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

