-- Table: rooms
CREATE TABLE IF NOT EXISTS `rooms` (
  `room_id` varchar(20) NOT NULL,
  `room_name` varchar(100) NOT NULL,
  `building` varchar(100) NOT NULL,
  `capacity` int NOT NULL,
  `room_type` varchar(30) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'AVAILABLE',
  PRIMARY KEY (`room_id`),
  CONSTRAINT `rooms_chk_1` CHECK ((`capacity` > 0)),
  CONSTRAINT `rooms_chk_2` CHECK ((`room_type` in (_cp850'CLASSROOM',_cp850'LAB',_cp850'LECTURE_HALL'))),
  CONSTRAINT `rooms_chk_3` CHECK ((`status` in (_cp850'AVAILABLE',_cp850'UNAVAILABLE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

