-- Table: sections
CREATE TABLE IF NOT EXISTS `sections` (
  `section_id` varchar(30) NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `term_id` varchar(20) NOT NULL,
  `room_id` varchar(20) DEFAULT NULL,
  `section_number` int NOT NULL,
  `capacity` int NOT NULL,
  `scheduled_start` datetime DEFAULT NULL,
  `scheduled_end` datetime DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PROPOSED',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`section_id`),
  UNIQUE KEY `course_id` (`course_id`,`term_id`,`section_number`),
  KEY `term_id` (`term_id`),
  KEY `room_id` (`room_id`),
  CONSTRAINT `sections_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `sections_ibfk_2` FOREIGN KEY (`term_id`) REFERENCES `academic_terms` (`term_id`),
  CONSTRAINT `sections_ibfk_3` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`room_id`),
  CONSTRAINT `sections_chk_1` CHECK ((`capacity` > 0)),
  CONSTRAINT `sections_chk_2` CHECK ((`section_number` > 0)),
  CONSTRAINT `sections_chk_3` CHECK ((`status` in (_cp850'PROPOSED',_cp850'SCHEDULED',_cp850'ACTIVE',_cp850'COMPLETED',_cp850'CANCELLED'))),
  CONSTRAINT `sections_chk_4` CHECK (((`scheduled_end` is null) or (`scheduled_start` is null) or (`scheduled_end` > `scheduled_start`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

