-- Table: student_course_history
CREATE TABLE IF NOT EXISTS `student_course_history` (
  `history_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` varchar(20) NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `term_id` varchar(20) NOT NULL,
  `enrollment_status` varchar(20) NOT NULL,
  `final_grade` varchar(5) DEFAULT NULL,
  `enrolled_at` date NOT NULL,
  PRIMARY KEY (`history_id`),
  KEY `student_id` (`student_id`),
  KEY `course_id` (`course_id`),
  KEY `term_id` (`term_id`),
  CONSTRAINT `student_course_history_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`),
  CONSTRAINT `student_course_history_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `student_course_history_ibfk_3` FOREIGN KEY (`term_id`) REFERENCES `academic_terms` (`term_id`),
  CONSTRAINT `student_course_history_chk_1` CHECK ((`enrollment_status` in (_cp850'ENROLLED',_cp850'COMPLETED',_cp850'DROPPED',_cp850'FAILED')))
) ENGINE=InnoDB AUTO_INCREMENT=6001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

