-- Table: student_plans
CREATE TABLE IF NOT EXISTS `student_plans` (
  `plan_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` varchar(20) NOT NULL,
  `program_id` varchar(20) NOT NULL,
  `term_id` varchar(20) NOT NULL,
  `current_semester` tinyint NOT NULL,
  `plan_status` varchar(20) DEFAULT 'ACTIVE',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`plan_id`),
  KEY `student_id` (`student_id`),
  KEY `program_id` (`program_id`),
  KEY `term_id` (`term_id`),
  CONSTRAINT `student_plans_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`),
  CONSTRAINT `student_plans_ibfk_2` FOREIGN KEY (`program_id`) REFERENCES `programs` (`program_id`),
  CONSTRAINT `student_plans_ibfk_3` FOREIGN KEY (`term_id`) REFERENCES `academic_terms` (`term_id`),
  CONSTRAINT `student_plans_chk_1` CHECK ((`current_semester` between 1 and 12)),
  CONSTRAINT `student_plans_chk_2` CHECK ((`plan_status` in (_cp850'ACTIVE',_cp850'COMPLETED',_cp850'CANCELLED')))
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

