-- Table: unmet_demand
CREATE TABLE IF NOT EXISTS `unmet_demand` (
  `unmet_id` bigint NOT NULL AUTO_INCREMENT,
  `forecast_id` bigint NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `term_id` varchar(20) NOT NULL,
  `unmet_quantity` int NOT NULL,
  `issue_type` varchar(50) NOT NULL,
  `resolution_status` varchar(20) DEFAULT 'OPEN',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`unmet_id`),
  KEY `forecast_id` (`forecast_id`),
  KEY `course_id` (`course_id`),
  KEY `term_id` (`term_id`),
  CONSTRAINT `unmet_demand_ibfk_1` FOREIGN KEY (`forecast_id`) REFERENCES `demand_forecasts` (`forecast_id`),
  CONSTRAINT `unmet_demand_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`course_id`),
  CONSTRAINT `unmet_demand_ibfk_3` FOREIGN KEY (`term_id`) REFERENCES `academic_terms` (`term_id`),
  CONSTRAINT `unmet_demand_chk_1` CHECK ((`unmet_quantity` > 0)),
  CONSTRAINT `unmet_demand_chk_2` CHECK ((`resolution_status` in (_cp850'OPEN',_cp850'RESOLVED',_cp850'CLOSED')))
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table: workload_assignments
CREATE TABLE IF NOT EXISTS `workload_assignments` (
  `assignment_id` varchar(30) NOT NULL,
  `section_id` varchar(30) NOT NULL,
  `faculty_id` varchar(20) NOT NULL,
  `assigned_hours` decimal(5,2) NOT NULL,
  `assignment_role` varchar(30) DEFAULT 'PRIMARY',
  `status` varchar(20) NOT NULL DEFAULT 'PROPOSED',
  `assigned_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`assignment_id`),
  KEY `section_id` (`section_id`),
  KEY `faculty_id` (`faculty_id`),
  CONSTRAINT `workload_assignments_ibfk_1` FOREIGN KEY (`section_id`) REFERENCES `sections` (`section_id`),
  CONSTRAINT `workload_assignments_ibfk_2` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`faculty_id`),
  CONSTRAINT `workload_assignments_chk_1` CHECK ((`assigned_hours` > 0)),
